package net.battlespades;

import java.util.*;
import java.io.*;
import java.util.zip.InflaterInputStream;
import net.battlespades.ugc.*;
import net.battlespades.protocol.*;
import net.battlespades.world.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class UgcProjectTest {
    private static UgcProject project(){return new UgcProject("","","","grassland","ctf");}
    @Test void multiModeRequirementsTagsAndUnsignedHandleSurviveRetailSidecar(){var p=project();for(int i=0;i<6;i++)p.place(i,0,10,i%3);p.place(new UgcProject.Placement(20,0,10,7,"nor"));p.place(new UgcProject.Placement(21,0,10,4,"nor"));p.place(22,0,10,13);p.place(23,0,10,10);assertTrue(p.validation().complete());assertEquals(List.of("tdm","ctf","vip","zom"),p.publishableModes());p.prefabSet(0);p.groundColors(List.of(List.of(-1,256,3,4)));var copy=UgcProject.parse("\ufeff"+p.json(),"fallback",null);assertEquals(p.placements(),copy.placements());assertEquals("18446744073709551615",copy.handle().toString());assertEquals(List.of("map","tdm","ctf","vip","zom"),copy.tags());assertEquals(List.of(255,0,3,4),copy.groundColors().getFirst());assertEquals("lunar",copy.prefabTerrain().key());copy.targetMode("territory");assertEquals(2,copy.validation().objectives().stream().filter(r->r.id().contains("NEUTRAL")).findFirst().orElseThrow().minimum());assertFalse(copy.validation().complete());}
    @Test void removalUsesVisibleModeItemDistanceAndNewestIdentity(){var p=project();var hidden=new UgcProject.Placement(10,10,10,7,"tdm");var visible=new UgcProject.Placement(10,10,10,4,"ctf");var nearby=new UgcProject.Placement(11,10,10,7,"nor");p.place(hidden);p.place(visible);p.place(nearby);assertEquals(nearby,p.remove(10,10,10,7).orElseThrow());assertEquals(visible,p.remove(10,10,10,7).orElseThrow());assertEquals(hidden,p.remove(10,10,10,null).orElseThrow());assertTrue(p.remove(Integer.MIN_VALUE,10,10,null).isEmpty());assertTrue(p.placements().isEmpty());assertFalse(p.place(1,2,3,3).isEmpty());assertEquals("oc",p.placements().getFirst().mode());assertTrue(p.place(1,2,3,3).isEmpty());}
    @Test void projectBoundsNormalizationAndAllModeLimits(){assertEquals(448,UgcCatalog.PREFABS.size());assertEquals(19,UgcCatalog.ITEMS.size());assertEquals("My_Map",UgcProject.slug(" ../ My Map - "));var p=new UgcProject("🂡".repeat(100),"\0 ","", "WATERBASEPLATE.vxl","zombie");assertEquals(80,p.title().codePointCount(0,p.title().length()));assertEquals("Undescribed UGC",p.description());assertEquals("zom",p.targetMode());for(var m:UgcProject.MODES){assertEquals(m,UgcProject.modeCode(UgcProject.modeId(m)));assertFalse(p.validation(m).complete());}assertThrows(IllegalArgumentException.class,()->UgcProject.parse("[]","x",null));assertThrows(IllegalArgumentException.class,()->UgcProject.parse("{\"ugc_entities\":[{\"position\":[512,0,0],\"item\":0}]}","x",null));assertThrows(IllegalArgumentException.class,()->UgcProject.parse("{\"prefab_set\":true}","x",null));assertThrows(IllegalArgumentException.class,()->UgcProject.modeCode(12));assertThrows(IllegalArgumentException.class,()->p.prefabSet(6));assertEquals("Untitled UGC",project().title());assertFalse(p.title("bad\nname"));}
    @Test void capacityParsesImplicitSolidsCenteredWaterAndTracksCanonicalMutations(){var raw=new Wire.Writer().u8(0).u8(100).u8(239).u8(0);for(int i=0;i<140;i++)raw.i32(0x123456);byte[] bytes=raw.toByteArray();var c=UgcCapacity.fromVxl(bytes);assertEquals(140,c.solids());assertEquals(9,c.chunks());assertTrue(c.solid(255,255,100));assertFalse(c.solid(0,0,239));assertEquals(0,UgcCapacity.fromVxl(new byte[]{0,(byte)240,(byte)239,0}).solids());assertThrows(IllegalArgumentException.class,()->UgcCapacity.fromVxl(new byte[]{0,0,1,0}));try(var world=new MutableWorld(VxlMap.load(bytes,"retail"),1,128)){var tracked=UgcCapacity.fromVxl(bytes).track(world);var cell=new MutableWorld.Cell(255,255,99);world.set(cell,true,1,null);assertEquals(141,tracked.solids());world.set(cell,true,2,null);assertEquals(141,tracked.solids());world.destroyBlocks(List.of(cell));assertEquals(140,tracked.solids());tracked.close();world.set(cell,true,3,null);assertEquals(140,tracked.solids());}assertTrue(UgcCapacity.hasSpace(2_800_000,3199));assertFalse(UgcCapacity.hasSpace(2_800_000,3200));assertTrue(UgcCapacity.hasSpace(2_799_999,3200));assertEquals(15359,UgcCapacity.chunkIndex(511,511,239));}
    @Test void nativeEditorPacketsUseRawShortsUintCountsAndRejectMalformedLengths(){var packets=List.<GamePacket>of(new UgcPackets.Batch(List.of(new UgcPackets.Item(8,1,2,3,7))),new UgcPackets.Objectives(8,List.of(new UgcPackets.Objective("A",-7))),new UgcPackets.Preview(new byte[]{1,2,3}),new UgcPackets.GroundColors(List.of(new UgcPackets.Color(1,2,3,4))));var hex=HexFormat.of();var nativeBytes=List.of("62010000000801000200030007","4408010000004100f9ffffff","6603000000010203","760101020304");for(int i=0;i<packets.size();i++){byte[] bytes=hex.parseHex(nativeBytes.get(i));assertArrayEquals(bytes,packets.get(i).encode());assertArrayEquals(bytes,PacketCodec.decode(bytes).encode());assertTrue(PacketCodec.supports(packets.get(i).id()));}for(byte[] invalid:List.of(hex.parseHex("62ffffffff"),hex.parseHex("62ffffff7f"),hex.parseHex("440841000000"),hex.parseHex("66ffffffff"),hex.parseHex("760201020304")))assertThrows(IllegalArgumentException.class,()->PacketCodec.decode(invalid));byte[] preview={1,2};var packet=new UgcPackets.Preview(preview);preview[0]=3;assertEquals(1,packet.data()[0]);packet.data()[0]=4;assertEquals(1,packet.data()[0]);}
    @Test void preparedVxlIsOneZlibStreamBeforeEndAndBatchesRemainBounded()throws Exception{byte[] raw=new byte[200_123];new Random(481).nextBytes(raw);var packets=UgcWire.source(raw);assertEquals(54,packets.getFirst().id());assertEquals(58,packets.getLast().id());var compressed=new ByteArrayOutputStream();int percent=0;for(var p:packets.subList(1,packets.size()-1)){var decoded=(LoadingPackets.MapChunk)PacketCodec.decode(p.encode());assertEquals(56,decoded.id());assertTrue(decoded.percent()>=percent&&decoded.percent()<=100);assertTrue(decoded.data().length<=32767);percent=decoded.percent();compressed.writeBytes(decoded.data());}assertEquals(100,percent);try(var input=new InflaterInputStream(new ByteArrayInputStream(compressed.toByteArray()))){assertArrayEquals(raw,input.readAllBytes());}var p=project();assertEquals(1,UgcWire.batches(p).size());for(int i=0;i<1025;i++)p.place(i%512,i/512,20,0);var batches=UgcWire.batches(p);assertEquals(List.of(512,512,1),batches.stream().map(x->((UgcPackets.Batch)x).items().size()).toList());assertEquals(1025,batches.stream().mapToInt(x->((UgcPackets.Batch)PacketCodec.decode(x.encode())).items().size()).sum());}
}
